const std::vector<const KernelSpec*>& all_kernels() {
    static const std::vector<const KernelSpec*> v = [] {
        std::vector<const KernelSpec*> r;
        for (const auto& k : kKernels) r.push_back(&k);
        return r;
    }();
    return v;
}

const KernelSpec& get_kernel(const std::string& name) {
    std::string n = name;
    std::transform(n.begin(), n.end(), n.begin(), [](unsigned char ch) { return std::tolower(ch); });
    std::replace(n.begin(), n.end(), '-', '_');
    std::replace(n.begin(), n.end(), ' ', '_');
    if (n == "cubic" || n == "cubic_spline" || n == "m4") return kKernels[0];
    if (n == "quartic" || n == "quartic_spline" || n == "m5") return kKernels[1];
    if (n == "quintic" || n == "quintic_spline" || n == "m6") return kKernels[2];
    if (n == "wendland_c2" || n == "wendlandc2" || n == "wc2") return kKernels[3];
    if (n == "wendland_c4" || n == "wendlandc4" || n == "wc4") return kKernels[4];
    if (n == "wendland_c6" || n == "wendlandc6" || n == "wc6") return kKernels[5];
    throw std::invalid_argument("unknown kernel '" + name + "' (expected one of: cubic_spline, quartic_spline, quintic_spline, wendland_c2, wendland_c4, wendland_c6)");
}

